#include <stdio.h>
#include <string.h>
#include <stdint.h>

int main(void) {
    float f = 1.0f;
    uint32_t bits;
    memcpy(&bits, &f, sizeof bits);
    printf("float 1.0 -> 0x%08X\n", bits);
    double d = -2.0;
    uint64_t dbits;
    memcpy(&dbits, &d, sizeof dbits);
    printf("double -2.0 -> 0x%016llX\n", (unsigned long long)dbits);
    return 0;
}
